from calc1_core import *
import mpmath as mp
mp.mp.dps=45
D=CalcDoc('1.4',[50],lambda n:50)
def add(n,st,steps,ans,check,parts=()):return D.add(n,('할선·접선과 순간변화율','Secants,tangents,and instantaneous rates'),st,('할선 기울기 Δy/Δx를 계산하고 기준점으로 다가갈 때의 값을 비교한다.','Compute the secant slope Δy/Δx and compare values as the second point approaches the base point.'),steps,ans,check,parts)
def table(pairs,digits=6):return '; '.join(str(t)+' → '+f'{float(v):.{digits}f}'for t,v in pairs)
data1=[(5,694),(10,444),(15,250),(20,111),(25,28),(30,0)];sl1=[(t,s.Rational(v-250,t-15))for t,v in data1 if t!=15]
add(1,('1000 gallon 탱크가30분에 비워진다. (t분,V gallon) 표='+str(data1)+'에서 P=(15,250).(a)t=5,10,20,25,30의 할선 기울기,(b)가까운 두 할선 평균으로 접선 기울기,(c)그래프에서15분 유출률을 추정하라.','A1000-gallon tank empties in30 minutes. Using(t in min,V in gal)='+str(data1)+' and P=(15,250),find(a)secant slopes at t=5,10,20,25,30,(b)a tangent estimate by averaging two nearby secants,(c)a graphical flow-rate estimate at15 minutes.'),[(d(r'm_{PQ}=\frac{V(t)-250}{t-15}'),d(r'm_{PQ}=\frac{V(t)-250}{t-15}')),(table(sl1,4),table(sl1,4)),('가장 가까운 양쪽 시각10,20의 기울기를 평균하면(−38.8−27.8)/2=−33.3 gallon/min이다.','Average the nearest slopes at10 and20:(−38.8−27.8)/2=−33.3 gal/min.')],('(a)−44.4,−38.8,−27.8,−22.2,−16.6667 gallon/min.(b,c)약−33.3 gallon/min; 물이 나가는 양의 속률은 약33.3 gallon/min.','(a)−44.4,−38.8,−27.8,−22.2,−16.6667 gal/min.(b,c)Approximately−33.3 gal/min;the positive outflow rate is about33.3 gal/min.'),('음의 기울기는 남아 있는 물의 감소를 뜻한다. 그림의 매끄러운 보조곡선1000(1−t/30)²는 표를0.45 gallon 이내로 근사하며 실제 정확한 법칙으로 가정하지 않는다.','The negative slope means remaining volume decreases. The smooth plotting guide1000(1−t/30)² approximates the table within0.45 gal and is not asserted as an exact law.'),list('abc'))
D.fig(1,[panel('Volume and tangent estimate',(0,30,0,1050),[samples(lambda z:1000*(1-z/30)**2,0,30),[(8,250-33.3*(8-15)),(22,250-33.3*(22-15))]],data1,xlabel='min',ylabel='gal')],('관측점·근사 곡선과15분의 접선 추정.','Observed points,a smooth approximation,and the estimated tangent at15 min.'))
data2=[(0,3438),(10,4559),(20,5622),(30,6536),(40,7398)]
add(2,('오후3시 후 t분의 누적 걸음수 표='+str(data2)+'이다.(a)[0,40],[10,20],[20,30]의 할선 기울기와 의미,(b)3:20의 걸음/분을 두 기울기 평균으로 추정하라.','Cumulative steps at t minutes after3 PM are '+str(data2)+'.(a)Find secant slopes on[0,40],[10,20],[20,30] and interpret them.(b)Estimate steps/min at3:20 by averaging nearby slopes.'),[('(a)(7398−3438)/40=99,(5622−4559)/10=106.3,(6536−5622)/10=91.4이다. 이는 각 구간의 평균 걸음 속도이다.','(a)(7398−3438)/40=99,(5622−4559)/10=106.3,(6536−5622)/10=91.4.These are average walking rates over the intervals.'),('(b)t=20의 양쪽 평균은(106.3+91.4)/2=98.85이다.','(b)The average of the two adjacent rates is(106.3+91.4)/2=98.85.')],('(a)99,106.3,91.4 걸음/분.(b)약98.85 걸음/분.','(a)99,106.3,91.4 steps/min.(b)Approximately98.85 steps/min.'),('동일한20분 중앙 구간의 기울기(6536−4559)/20도98.85이다. 누적 걸음수 자체를 시간으로 나누지 않았다.','The centered slope(6536−4559)/20 also gives98.85. The calculation uses changes in cumulative steps rather than the cumulative total divided by time.'),list('ab'))
x3=['1.5','1.9','1.99','1.999','2.5','2.1','2.01','2.001'];s3=[(q,1/(mp.mpf(q)-1))for q in x3]
add(3,('P=(2,−1)은 y=1/(1−x) 위의 점이다.(a)x='+','.join(x3)+'인 Q와의 할선 기울기를 소수6자리로,(b)접선 기울기 추정,(c)접선식을 구하라.','P=(2,−1) lies on y=1/(1−x).Find(a)secant slopes to Q at x='+','.join(x3)+' to6 decimals,(b)the estimated tangent slope,(c)the tangent equation.'),[(d(r'm(x)=\frac{1/(1-x)+1}{x-2}=\frac1{x-1}\quad(x\ne1,2)'),d(r'm(x)=\frac{1/(1-x)+1}{x-2}=\frac1{x-1}\quad(x\ne1,2)')),(table(s3),table(s3)),('x가2로 양쪽에서 가까워지면 기울기는1로 다가간다. 점기울기식은 y+1=x−2이다.','As x approaches2 from either side,the slope approaches1. Point-slope form is y+1=x−2.')],('(a)'+table(s3)+';(b)1;(c)y=x−3.','(a)'+table(s3)+';(b)1;(c)y=x−3.'),('원래 할선식과 단순화식의 차를 기호적으로0으로 확인했고 접선은(2,−1)을 지난다.','The original and simplified secant expressions have symbolic difference zero;the tangent passes through(2,−1).'),list('abc'))
x4=['0','0.4','0.49','0.499','1','0.6','0.51','0.501'];s4=[(q,mp.cos(mp.pi*mp.mpf(q))/(mp.mpf(q)-mp.mpf('.5')))for q in x4]
add(4,('P=(0.5,0)은 y=cos(πx) 위의 점이다.(a)x='+','.join(x4)+'에서 할선 기울기를6자리로,(b)접선 기울기,(c)접선식,(d)곡선·할선 둘·접선을 그려라.','P=(0.5,0) lies on y=cos(πx).Find(a)secant slopes at x='+','.join(x4)+' to6 decimals,(b)tangent slope,(c)tangent equation,and(d)plot the curve,two secants,and tangent.'),[(d(r'm(x)=\frac{\cos(\pi x)}{x-1/2}'),d(r'm(x)=\frac{\cos(\pi x)}{x-1/2}')),(table(s4),table(s4)),('x=1/2+h로 쓰면 기울기는−sin(πh)/h이며 h→0에서−π로 다가간다.','With x=1/2+h,the slope is−sin(πh)/h,which approaches−π as h→0.')],('(a)'+table(s4)+';(b)−π≈−3.141593;(c)'+m(r'y=-\pi(x-1/2)')+';(d)첨부 그래프.','(a)'+table(s4)+';(b)−π≈−3.141593;(c)'+m(r'y=-\pi(x-1/2)')+';(d)attached graph.'),('h와−h에서 같은 할선 기울기를 얻는다. 접선에 x=1/2를 넣으면0이며 독립 미분 검산도−π이다.','The slopes agree for h and−h. The tangent gives0 at x=1/2;independent differentiation also gives−π.'),list('abcd'))
D.fig(4,[panel('Curve blue; secants red/green; tangent purple',(-.2,1.2,-1.5,1.5),[samples(lambda z:math.cos(math.pi*z),-.2,1.2),samples(lambda z:-2*(z-.5),-.2,1.2),samples(lambda z:(math.cos(.4*math.pi)/(-.1))*(z-.5),-.2,1.2),samples(lambda z:-math.pi*(z-.5),-.2,1.2)],[(.5,0)])])
add(5,('강 수면에서275 ft 높은 다리에서 떨어지는 돌의 높이는 y=275−16t²이다.(a)t=4부터0.1,0.05,0.01초 구간 평균속도,(b)4초 순간속도를 추정하라.','A stone dropped from a275-ft bridge has height y=275−16t² above the river.Find(a)average velocities starting at t=4 for durations0.1,0.05,0.01 s,and(b)instantaneous velocity at4 s.'),[(d(r'\frac{y(4+h)-y(4)}h=\frac{-128h-16h^2}h=-128-16h'),d(r'\frac{y(4+h)-y(4)}h=\frac{-128h-16h^2}h=-128-16h')),('h가0으로 가면 상수항−128만 남는다.','As h tends to zero,the limit is−128.')],('(a)−129.6,−128.8,−128.16 ft/s.(b)−128 ft/s,즉 아래로128 ft/s.','(a)−129.6,−128.8,−128.16 ft/s.(b)−128 ft/s,or128 ft/s downward.'),('4.1초에도 y=6.04 ft>0이어서 세 구간은 모두 수면 충돌 전이다.','At4.1 s the height is still6.04 ft>0,so all three intervals occur before impact.'),list('ab'))
steps6=['1','0.5','0.1','0.01','0.001'];v6=[(h,mp.mpf('6.28')-mp.mpf('1.86')*mp.mpf(h))for h in steps6]
add(6,('화성에서 위로 던진 돌의 높이는 y=10t−1.86t²(m)이다.(a)[1,2],[1,1.5],[1,1.1],[1,1.01],[1,1.001]의 평균속도,(b)t=1 순간속도를 구하라.','On Mars a thrown rock has height y=10t−1.86t²(m).Find(a)average velocities on[1,2],[1,1.5],[1,1.1],[1,1.01],[1,1.001],and(b)instantaneous velocity at t=1.'),[(d(r'\frac{y(1+h)-y(1)}h=10-1.86(2+h)=6.28-1.86h'),d(r'\frac{y(1+h)-y(1)}h=10-1.86(2+h)=6.28-1.86h')),(table(v6,5),table(v6,5))],('(a)4.42,5.35,6.094,6.2614,6.27814 m/s.(b)6.28 m/s.','(a)4.42,5.35,6.094,6.2614,6.27814 m/s.(b)6.28 m/s.'),('h를 줄이면 양의 평균속도가6.28로 증가하며 위로 이동 중이라는 부호와 맞는다.','As h shrinks,the positive average velocity rises toward6.28,consistent with upward motion.'),list('ab'))
data7=[(0,0),(1,4.9),(2,20.6),(3,46.5),(4,79.2),(5,124.8),(6,176.7)]
add(7,('정지에서 출발한 오토바이의(t초,s ft) 표='+str(data7)+'이다.(a)[2,4],[3,4],[4,5],[4,6]의 평균속도,(b)그래프로 t=3 순간속도를 추정하라.','A motorcycle accelerating from rest has(t seconds,s feet) data '+str(data7)+'.Find(a)average velocities on[2,4],[3,4],[4,5],[4,6],and(b)estimate instantaneous velocity at t=3 from a graph.'),[('(a)각 구간에서 위치차/시간차를 계산하면29.3,32.7,45.6,48.75이다.','(a)Position change divided by time change gives29.3,32.7,45.6,48.75.'),('(b)t=3 양쪽의1초 기울기는25.9와32.7이다. 평균29.3을 접선 기울기로 택하면 약29~30 ft/s이다.','(b)The adjacent1-second slopes at t=3 are25.9 and32.7.Their average29.3 estimates the tangent slope,about29–30 ft/s.')],('(a)29.3,32.7,45.6,48.75 ft/s.(b)약29.3 ft/s(그래프에 따라 약30도 타당).','(a)29.3,32.7,45.6,48.75 ft/s.(b)Approximately29.3 ft/s(about30 is also a reasonable graph estimate).'),('2~4초의 세 점을 지나는 이차 보간식은46.5+29.3(t−3)+3.4(t−3)²로 중앙 기울기29.3을 확인한다. 이산 자료만으로 정확한 순간속도를 확정하지 않는다.','The local quadratic through t=2,3,4 is46.5+29.3(t−3)+3.4(t−3)²,confirming central slope29.3.Discrete data do not determine an exact instantaneous velocity.'),list('ab'))
D.fig(7,[panel('Position and local tangent estimate',(0,6,0,185),[data7,samples(lambda z:46.5+29.3*(z-3)+3.4*(z-3)**2,2,4),[(1.5,46.5+29.3*(1.5-3)),(4.5,46.5+29.3*(4.5-3))]],data7,xlabel='s',ylabel='ft')])
ht8=['1','0.1','0.01','0.001'];v8=[(z,(-2*mp.sin(mp.pi*mp.mpf(z))+3*(1-mp.cos(mp.pi*mp.mpf(z))))/mp.mpf(z))for z in ht8]
add(8,('위치 s(t)=2sin(πt)+3cos(πt)(cm),t초이다.(a)[1,2],[1,1.1],[1,1.01],[1,1.001]의 평균속도,(b)t=1의 순간속도를 추정하라.','Position is s(t)=2sin(πt)+3cos(πt) cm at time t seconds.Find(a)average velocity on[1,2],[1,1.1],[1,1.01],[1,1.001],and(b)instantaneous velocity at1 second.'),[('s(1)=−3이고 t=1+h를 대입해 차분몫을 정리한다.','Since s(1)=−3,substitute t=1+h and simplify the difference quotient.'),(d(r'\frac{s(1+h)-s(1)}h=\frac{-2\sin(\pi h)+3(1-\cos(\pi h))}h'),d(r'\frac{s(1+h)-s(1)}h=\frac{-2\sin(\pi h)+3(1-\cos(\pi h))}h')),(table(v8),table(v8))],('(a)h=1,0.1,0.01,0.001 순서 '+', '.join(f'{float(v):.6f}'for h,v in v8)+' cm/s.(b)−2π≈−6.283185 cm/s.','(a)For h=1,0.1,0.01,0.001: '+', '.join(f'{float(v):.6f}'for h,v in v8)+' cm/s.(b)−2π≈−6.283185 cm/s.'),('sin(πh)/h→π이고(1−cos(πh))/h→0이므로 극한은−2π이다. 긴 구간 평균이 양수여도 순간속도는 음수일 수 있다.','Since sin(πh)/h→π and(1−cos(πh))/h→0,the limit is−2π.A positive long-interval average does not force positive instantaneous velocity.'),list('ab'))
xs9=['2','1.5','1.4','1.3','1.2','1.1','0.5','0.6','0.7','0.8','0.9'];v9=[(z,mp.sin(10*mp.pi/mp.mpf(z))/(mp.mpf(z)-1))for z in xs9];near=['0.99','1.01','0.999','1.001','0.9999','1.0001'];vn=[(z,mp.sin(10*mp.pi/mp.mpf(z))/(mp.mpf(z)-1))for z in near]
add(9,('P=(1,0)은 y=sin(10π/x) 위의 점이다.(a)x='+','.join(xs9)+'의 할선 기울기를4자리로 구해 수렴처럼 보이는지 설명하고,(b)그래프로 이 선택의 문제를 설명하고,(c)더 가까운 Q로 접선 기울기를 추정하라.','P=(1,0) lies on y=sin(10π/x).(a)Find4-decimal secant slopes at x='+','.join(xs9)+' and discuss apparent convergence;(b)use a graph to explain why these secants are poor approximations;(c)choose closer Q to estimate the tangent slope.'),[(d(r'm(x)=\frac{\sin(10\pi/x)}{x-1}'),d(r'm(x)=\frac{\sin(10\pi/x)}{x-1}')),(table(v9,4),table(v9,4)),('이 넓은 간격에서는 여러 번 진동하므로 값들이 접선 기울기로 수렴하는 모습이 뚜렷하지 않다. x=1의 아주 가까운 구간을 확대해야 한다.','Across these broad intervals the curve oscillates repeatedly,so the slopes do not visibly approach the tangent value.Zoom into a much smaller neighborhood of1.'),(table(vn,6),table(vn,6))],('(a)'+table(v9,4)+';(b)빠른 진동 때문에 너무 먼 점을 선택했다.(c)약−31.416,정확한 극한은−10π.','(a)'+table(v9,4)+';(b)The points are too far away relative to the oscillation.(c)Approximately−31.416;the exact limit is−10π.'),('x=1+h이면10π/x=10π−10πh/(1+h),따라서 차분몫은−sin(10πh/(1+h))/h→−10π이다.','For x=1+h,10π/x=10π−10πh/(1+h),so the quotient is−sin(10πh/(1+h))/h→−10π.'),list('abc'))
D.fig(9,[panel('Wide view: oscillating curve',(.5,2,-1.2,1.2),[samples(lambda z:math.sin(10*math.pi/z),.5,2,1200)],[(1,0)]),panel('Zoom: curve blue;tangent red',(.99,1.01,-.35,.35),[samples(lambda z:math.sin(10*math.pi/z),.99,1.01),samples(lambda z:-10*math.pi*(z-1),.99,1.01)],[(1,0)])])
D.save(9)
